```python
"""A background worker that drains a queue.Queue, handing each item to a callback."""

import logging
import queue
import threading

log = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Runs `callback(item)` on a daemon thread for every item put on the queue."""

    def __init__(self, callback, q=None, name="queue-worker"):
        self.callback = callback
        self.queue = q if q is not None else queue.Queue()
        self._thread = threading.Thread(target=self._run, name=name, daemon=True)
        self._started = False

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()
        return self

    def submit(self, item):
        self.queue.put(item)

    def _run(self):
        while True:
            item = self.queue.get()
            try:
                if item is _SHUTDOWN:
                    return
                self.callback(item)
            except Exception:
                # One bad item shouldn't take the worker down.
                log.exception("worker callback failed on %r", item)
            finally:
                self.queue.task_done()

    def join_queue(self):
        """Block until everything submitted so far has been processed."""
        self.queue.join()

    def stop(self, timeout=None):
        """Ask the worker to finish the backlog, then exit."""
        if not self._started:
            return
        self.queue.put(_SHUTDOWN)
        self._thread.join(timeout)

    def __enter__(self):
        return self.start()

    def __exit__(self, *exc):
        self.stop()
        return False
```

Notes on the design: the sentinel goes through the queue rather than a flag, so `stop()` drains the backlog first instead of cutting it off mid-flight. Exceptions from the callback are logged and swallowed — if you'd rather have failures propagate, pass a callback that pushes them onto a result queue. `join_queue()` uses the standard `task_done`/`join` pairing, so it returns once the pending items are done but does not stop the thread.
